def closest_pair_gap(sizes, target):
    s = sorted(sizes)
    lo, hi = 0, len(s) - 1
    best = abs(s[lo] + s[hi] - target)
    while lo < hi:
        total = s[lo] + s[hi]
        best = min(best, abs(total - target))
        if total < target:
            lo += 1
        elif total > target:
            hi -= 1
        else:
            return 0
    return best

