from bisect import bisect_left

def closest_pair_gap(sizes, target):
    s = sorted(sizes)
    best = abs(s[0] + s[1] - target)
    for i, x in enumerate(s):
        k = bisect_left(s, target - x)
        for j in (k - 1, k):
            if 0 <= j < len(s):
                best = min(best, abs(x + s[j] - target))
    return best
